scripts.卢青对话.txt:
// 卢青对话

	If ($Event == 10) @Event10;  //同伴
	If ($Event >= 20) @Event20;  //非同伴

@Event10:
	Say("卢青：大师兄，我们快去看看师傅吧。", 83);
	Say("独孤剑：好的。", 1);
	Return;
	
@Event20:
	If ($Talkluqin == 0) @Talk0;
	If ($Talkluqin == 1) @Talk1;
	If ($Talkluqin == 2) @Talk2;

@Talk0:
	Say("卢青：杀害师傅的凶手会不会真是五色教的刺客？", 83);
	Say("独孤剑：师傅说凶手象是五色教这个暗杀组织的人，但听说这个组织早就从武林中消失了。", 1);
	Say("卢青：难道是这个组织死灰复燃了？掌门师兄，你一定要把这件事搞个水落石出，为师傅报仇。", 83);
	Assign($Talkluqin, 1);
	Return;
@Talk1:	
	Say("卢青：师兄，你一路上要多加小心！", 83);
	Assign($Talkluqin, 2);
	Return;
@Talk2:	
	Say("卢青：师兄，你办完事后快些回来。", 83);
	Return;

scripts.曲霞对话.txt:
// 曲霞对话

	If ($Event >= 20) @Event20; 

@Event20:
	If ($Talkquxia == 0) @Talk0;
	If ($Talkquxia == 1) @Talk1;
	If ($Talkquxia == 2) @Talk2;
	If ($Talkquxia == 3) @Talk3;
@Talk0:
	Say("曲霞：大师兄，不，掌门师兄，师傅吩咐过丹心剑留给你，我给你拿来。", 0);
	Say("独孤剑：我现在武功低微，怎么敢使用师傅留下的宝剑？", 1);
	Assign($Talkquxia, 1);
	Return;
@Talk1:	
	Say("曲霞：师兄什么时候需要宝剑就吩咐一声。", 0);
	Assign($Talkquxia, 2);
	Return;
@Talk2:	
	Say("曲霞：房子里有些出门用得着的东西，师兄你多带一些在身边吧。", 0);
	Assign($Talkquxia, 3);
	Return;
@Talk3:
	Say("曲霞：师兄，你……一定要多多保重！", 0);
	Return;

