traps.Trap01.txt:
// 卧室门口

	If ($Event == 10) @Event10;  
	
@Event10:
	Say("独孤剑：师傅！", 6);
	SetNpcKind("卢青",0);
	PlayerGotoEx(8, 18);
	NpcGoto("卢青", 8, 19);
	SetPlayerDir(4);
	Say("独孤剑：师傅！", 6);
	PlayerRunTo(8, 14);
	PlayerGoto(7, 12);	
	SetPlayerDir(5);
	NpcGoto("卢青", 8, 14);
	SetNpcDir("卢青", 4); 
	
	SetNpcActionFile("独孤剑", 0, "mpc409_2.asf");
	SetNpcActionFile("独孤剑", 1, "mpc409_2.asf");
	NpcSpecialAction("独孤剑", "mpc409_1.asf");    // 独孤剑扑到师傅身上
	Sleep(1500);
	
	PlaySound("特_咳嗽.wav");

	Say("独孤剑：师傅，您怎么了？发生了什么事？……", 6);
	Say("刘轻舟：我被五色教的杀手追杀，勉力脱身回山……我把一份很重要的书信放在山下的……一块石头下，咳咳……", 203);
	Sleep(500);
	Say("刘轻舟：这封书信事关重大，你快去、快去找来……交、交给……", 203);
	Say("刘轻舟：武夷山柳、柳中原……",203);
	Sleep(500);
	Say("刘轻舟：咳咳……快去……",203);
	Say("独孤剑：师傅，您受了伤，我这就下山去给您找大夫……", 6);
	Say("刘轻舟：没有用的……我一路遭遇无数五色教高手劫杀，恶战数场，咳咳……如今体内的奇经八脉均已被震断，即便是杜神医在世恐怕也无力回天了……", 203);
	Say("独孤剑：不会的，师傅！", 6);
	Say("刘轻舟：剑儿，你是衡山派的大弟子，咳咳……为师死后，执掌衡山派的重任就落在你肩上了……", 203);
	Say("独孤剑：不！师傅，你不会死的！剑儿自幼父母双亡，是师傅抚育我长大成人，师傅，你对我恩重如山！剑儿不会让你死的！", 6);
	Say("刘轻舟：傻孩子，生死有命，何必强求？只恨，咳咳……外寇未灭！", 203);
	Sleep(500);	
	Say("刘轻舟：呃！……", 203);
	SetNpcActionFile("刘轻舟", 0, "mpc001_3.asf");
	SetNpcActionFile("刘轻舟", 1, "mpc001_3.asf");
	NpcSpecialAction("刘轻舟", "mpc001_2.asf");
	Sleep(1000);
	Say("独孤剑：师傅！", 7);
	Say("衡山派弟子：师傅！", 0);
	Sleep(500);
	
	FadeOut();
	StopMusic();
	PlayMusic("前途.mp3");
	Assign($Event, 15);
	Say("刘轻舟死后，独孤剑继承衣钵，成为衡山派的新掌门。", 0);
	LoadNpc("map003_event15.npc");
	SetNpcActionFile("独孤剑", 0, "npc001_st2.asf");
	SetNpcActionFile("独孤剑", 1, "npc001_sst2.asf");
	SetPlayerPos(8, 34);
	SetPlayerDir(1);
	SetPlayerScn();
	FadeIn();
	
	Say("卢青：师兄，师傅死得太惨了，我们一定要给师傅报仇！", 83);
	Say("独孤剑：不错！这个仇我们是一定要报的！只是眼下还有一件更紧迫的事要办，师傅临终前反复提到一封重要的书信，说是事关重大，我们必须尽快把它找到，以免落入歹人之手。", 1);
	Say("马涛：师兄说得对，这么重要的东西千万不能落在坏人手中。", 0);
	Say("独孤剑：所以我打算即刻下山找到书信，然后依照师嘱将书信交给武夷派柳中原前辈。下山期间，山中的事务就麻烦卢青师弟代为处理了。", 1);
	Say("卢青：师兄放心。五色教阴险诡秘，师兄此行一定要多加小心！", 83);
	Say("曲霞：师兄，你……要多加小心！速去速回！", 0);
	Say("独孤剑：嗯！", 1);

	SetMapTrap(1, "");
	SetMapTrap(2, "Trap02.txt");
	
	Memo("独孤剑见到师傅时，刘轻舟已经奄奄一息。他在临死前交待了两件事：一是自己是被五色教人追杀受的伤，二是他将一封非常重要的血书放在了山脚的一块石头下，嘱托独孤剑下山去取。 ");
	Memo("刘轻舟死后，独孤剑按照师傅遗愿继任衡山派掌门。他决定先去山下取血书。");
			
	Assign($Event, 20);
	Assign($Result, 0);
	
	Return;

